// src/core/residence/residence.schemas.ts
import { z } from 'zod';

export const setResidenceSchema = z.object({
  countryId: z.string().uuid('ID do país inválido').nullable().optional(),
  stateId: z.string().uuid('ID do estado inválido').nullable().optional(),
  cityId: z.string().uuid('ID da cidade inválida').nullable().optional(),
  timezone: z.string().max(100, 'Timezone deve ter no máximo 100 caracteres').nullable().optional(),
  currency: z.string().length(3, 'Moeda deve ter 3 caracteres (ISO 4217)').optional(),
  languages: z.array(z.string().min(2).max(10, 'Código de idioma inválido')).optional(),
});

export const setResidencePreferencesSchema = z.object({
  timezone: z.string().max(100, 'Timezone deve ter no máximo 100 caracteres').nullable().optional(),
  currency: z.string().length(3, 'Moeda deve ter 3 caracteres (ISO 4217)').optional(),
  languages: z.array(z.string().min(2).max(10, 'Código de idioma inválido')).optional(),
});
















